<template><div class="admin-applications-page"><AdminApplicationsTabs active="availability" :admin="isAdmin"/><DemoIdentitySwitcher/><div v-if="!canAccess" class="applications-state"><strong>Induction staff access required</strong></div><template v-else><header class="applications-page-header"><div><h1>Availability</h1><p>{{isAdmin?'Organisation-wide induction coverage and capacity.':'Your assigned hours, inductions, and unavailability.'}}</p></div><span class="demo-data-badge">Demo data</span></header><p class="outlook-demo-note">Outlook calendar connection is not active. These busy periods are fictional demo data.</p><section v-if="isAdmin" class="application-summary-grid induction-summary"><article v-for="x in summary" :key="x.label"><strong>{{x.value}}</strong><span>{{x.label}}</span></article></section><form class="application-filters induction-filters"><select v-model="filters.staff" aria-label="Filter staff"><option value="">All staff</option><option v-for="s in profiles" :key="s.id" :value="s.id">{{s.name}}</option></select><select v-model="filters.source" aria-label="Filter source"><option value="">All sources</option><option>Assigned hours</option><option>Staff unavailable</option><option>Fictional Outlook busy</option><option>Existing booking</option></select><button type="button" @click="filters={staff:'',source:''}">Reset</button></form><section class="application-panel"><h2>Availability calendar and mobile agenda</h2><div class="availability-legend"><span>Assigned hours</span><span>Staff unavailable</span><span>Outlook busy</span><span>Existing booking</span><span>Bookable capacity</span></div><div class="availability-agenda"><button v-for="x in visible" :key="x.id" @click="selected=x"><strong>{{x.staffName}}</strong><span>{{x.day}} · {{x.time}}</span><small>{{x.source}} · {{x.status}}</small></button></div></section><section class="application-panel"><h2>Availability records</h2><div class="applications-table-scroll"><table class="applications-table"><thead><tr><th>Staff</th><th>Date/day</th><th>Time</th><th>Zone</th><th>Source</th><th>Status</th><th>Effective</th><th>Conflict</th></tr></thead><tbody><tr v-for="x in visible" :key="x.id"><td>{{x.staffName}}</td><td>{{x.day}}</td><td>{{x.time}}</td><td>{{x.timeZone}}</td><td>{{x.source}}</td><td>{{x.status}}</td><td>{{x.effective}}</td><td>{{x.conflict||'None'}}</td></tr></tbody></table></div></section><div class="application-detail-grid"><form v-if="isAdmin" class="application-panel availability-form" @submit.prevent="saveHours"><h2>Add recurring induction hours</h2><label>Staff<select v-model="hours.staffId"><option v-for="s in profiles" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Day<select v-model.number="hours.day"><option v-for="(d,i) in days" :value="i">{{d}}</option></select></label><label>Start<input v-model="hours.start" type="time"/></label><label>End<input v-model="hours.end" type="time"/></label><label>Effective start<input v-model="hours.effectiveStart" type="date"/></label><label>Effective end<input v-model="hours.effectiveEnd" type="date"/></label><label>Duration<input v-model.number="hours.duration" type="number"/></label><label>Buffer before<input v-model.number="hours.bufferBefore" type="number"/></label><label>Buffer after<input v-model.number="hours.bufferAfter" type="number"/></label><label>Maximum per day<input v-model.number="hours.maxPerDay" type="number"/></label><p v-if="error" role="alert">{{error}}</p><button>Add recurring hours</button></form><form class="application-panel availability-form" @submit.prevent="saveAway"><h2>Report unavailability</h2><label v-if="isAdmin">Staff<select v-model="away.staffId"><option v-for="s in profiles" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Type<select v-model="away.type"><option>Holiday</option><option>Appointment</option><option>Personal unavailable time</option><option>Other</option></select></label><label>Start<input v-model="away.start" type="datetime-local"/></label><label>End<input v-model="away.end" type="datetime-local"/></label><label>Time zone<select v-model="away.timeZone"><option>Europe/London</option><option>Europe/Paris</option></select></label><label>Private optional reason<textarea v-model="away.privateReason"></textarea></label><p v-if="message" role="status">{{message}}</p><button>Save unavailable period</button></form></div><section v-if="!isAdmin" class="application-panel"><h2>My upcoming assigned inductions</h2><p v-for="b in myBookings" :key="b.id">{{b.date}} · {{b.startTime}} · {{b.applicantName}} <strong v-if="b.adminAttention==='Admin action required'">Admin action required</strong></p></section><div v-if="selected" class="event-summary"><div class="application-panel"><h2>{{selected.source}}</h2><p>{{selected.staffName}} · {{selected.day}} {{selected.time}}</p><p>No private Outlook content or private staff reason is shown.</p><button @click="selected=null">Close</button></div></div></template></div></template>
<script>
import AdminApplicationsTabs from './components/AdminApplicationsTabs.vue'; import DemoIdentitySwitcher from './components/DemoIdentitySwitcher.vue'; import { demoWorkflow, getDemoIdentity } from './applicationAdminData.js'; import { availabilityDemo, capacitySummary, createRecurringHours, DEMO_STAFF_PROFILES, reportUnavailability } from './inductionAvailabilityData.js';
export default { name:'AdminInductionAvailability', components:{AdminApplicationsTabs,DemoIdentitySwitcher}, data:()=>({workflow:demoWorkflow,state:availabilityDemo,profiles:DEMO_STAFF_PROFILES,filters:{staff:'',source:''},selected:null,error:'',message:'',days:['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],hours:{staffId:'riley-staff',day:1,start:'09:00',end:'12:00',timeZone:'Europe/London',effectiveStart:'2026-09-01',effectiveEnd:'',duration:60,bufferBefore:15,bufferAfter:15,maxPerDay:3},away:{staffId:'riley-staff',type:'Holiday',start:'2026-09-21T09:00',end:'2026-09-21T12:00',timeZone:'Europe/London',privateReason:''}}), computed:{identity(){this.workflow.revision;return getDemoIdentity()},isAdmin(){return this.identity.role==='admin'},canAccess(){return['admin','staff'].includes(this.identity.role)},summary(){this.state.revision;const s=capacitySummary();return Object.entries({activeStaff:'Active staff',availableHours:'Available hours',bookableSlots:'Bookable slots',bookedSlots:'Booked slots',staffUnavailable:'Staff unavailable',outlookLost:'Lost to Outlook busy',coverageGaps:'Coverage gaps',reassignment:'Require reassignment'}).map(([key,label])=>({label,value:s[key]}))},items(){this.state.revision;const name=id=>this.profiles.find(s=>s.id===id)?.name||id;return[...this.state.hours.map(x=>({id:x.id,staffId:x.staffId,staffName:name(x.staffId),day:this.days[x.day],time:`${x.start}–${x.end}`,timeZone:x.timeZone,source:'Assigned hours',status:x.active?'Active':'Inactive',effective:`${x.effectiveStart}–${x.effectiveEnd||'ongoing'}`})),...this.state.unavailability.filter(x=>x.status==='active').map(x=>({id:x.id,staffId:x.staffId,staffName:name(x.staffId),day:x.start.slice(0,10),time:`${x.start.slice(11)}–${x.end.slice(11)}`,timeZone:x.timeZone,source:'Staff unavailable',status:x.type,effective:'One-off',conflict:x.bookingConflict?'Admin action required':''})),...this.state.outlookBusy.map(x=>({id:x.id,staffId:x.staffId,staffName:name(x.staffId),day:x.start.slice(0,10),time:`${x.start.slice(11)}–${x.end.slice(11)}`,timeZone:'Europe/London',source:'Fictional Outlook busy',status:x.state,effective:'One-off'})),...this.workflow.inductions.filter(x=>x.date!=='Not booked').map(x=>({id:`b-${x.id}`,staffId:this.profiles.find(s=>s.name===x.assignedStaff)?.id,staffName:x.assignedStaff,day:x.date,time:`${x.startTime}–${x.endTime}`,timeZone:x.timeZone,source:'Existing booking',status:x.status,effective:'One-off',conflict:x.adminAttention}))]},visible(){const staff=this.isAdmin?this.filters.staff:this.identity.id;return this.items.filter(x=>(!staff||x.staffId===staff)&&(!this.filters.source||x.source===this.filters.source))},myBookings(){return this.workflow.inductions.filter(x=>x.assignedStaff===this.identity.name&&x.status==='booked')}},methods:{saveHours(){this.error='';try{createRecurringHours(this.hours)}catch(e){this.error=e.message}},saveAway(){try{const x=reportUnavailability({...this.away,staffId:this.isAdmin?this.away.staffId:this.identity.id});this.message=x.bookingConflict?'Saved. Existing induction affected; Admin action required.':'Unavailable period saved and slots updated.'}catch(e){this.message=e.message}}} };
</script><style src="./AdminApplications.css"></style>
